import java.util.Scanner;

class Cat {
    String name;
    int fish;

    void report() {
        System.out.println(name + " 今天吃了 " + fish + " 条小鱼干喵");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String who = sc.next();
        int n = sc.nextInt();

        Cat c = new Cat();
        c.name = who;
        c.fish = n;
        c.report();
    }
}
